// quot++\n339 0x0001 // Operand #0x0001 (1)\n340 0x2800 // Speichere quot\n341 0x03A6 // Operand #0x03A6 (934)\n342 0x4000 // Loop __div\n343 0x0140 // Operand #0x0140 (320)\n344 0x1800 // __div: Rueckgabe Quotient\n345 0x03A6 // Operand #0x03A6 (934)\n346 0x6000 // RETURN __div\n347 0x1800 // Lade Zeiger\n348 0x0398 // Operand #0x0398 (920)\n349 0x2800 // Patch Zieladresse\n350 0x0162 // Operand #0x0162 (354)\n351 0x1400 // Pixeldaten = 0\n353 0x2800 // Schreibe in Display\n355 0x1800 // Zeiger inkrementieren\n356 0x0398 // Operand #0x0398 (920)\n357 0x3440 // ptr++\n358 0x0001 // Operand #0x0001 (1)\n359 0x2800 // Speichere ptr\n360 0x0398 // Operand #0x0398 (920)\n361 0x1800 // Lade endCls\n362 0x0399 // Operand #0x0399 (921)\n363 0x3540 // ~endCls\n365 0x3440 // ~endCls + 1\n366 0x0001 // Operand #0x0001 (1)\n367 0x2800 // Patch Endvergleich\n368 0x0174 // Operand #0x0174 (372)\n369 0x1800 // Lade ptr\n370 0x0398 // Operand #0x0398 (920)\n371 0x3440 // ptr - endCls\n373 0x4018 // __cls: Fertig bei endCls\n374 0x0179 // Operand #0x0000 (0)\n375 0x4000 // Loop __cls\n376 0x015B // Operand #0x015B (347)\n377 0x6000 // RETURN __cls\n378 0x1800 // __pset: Lade Y\n379 0x03A4 // Operand #0x03A4 (932)\n380 0x35C0 // Y * 2\n382 0x3440 // Base + Y*2 + 1 (Default Word 1)\n383 0x03C1 // Operand #0x03C1 (961)\n384 0x2800 // Speichere wordAddr\n385 0x03A7 // Operand #0x03A7 (935)\n386 0x1800 // Lade X\n387 0x03A3 // Operand #0x03A3 (931)\n388 0x3480 // X >= 16 ?\n389 0x0010 // Operand #0x0010 (16)\n390 0x4018 // Wenn X < 16 -> Word 1 bereit\n391 0x018E // Operand #0x0000 (0)\n392 0x1800 // Lade wordAddr\n393 0x03A7 // Operand #0x03A7 (935)\n394 0x3440 // wordAddr - 1 -> Word 0\n395 0xFFFF // Operand #0xFFFF (65535)\n396 0x2800 // Speichere Word 0\n397 0x03A7 // Operand #0x03A7 (935)\n398 0x1400 // Init Maske = 0x8000 (Bit 15)\n399 0x8000 // Operand #0x8000 (32768)\n400 0x2800 // Speichere Startmaske\n401 0x03A8 // Operand #0x03A8 (936)\n402 0x1800 // Lade X\n403 0x03A3 // Operand #0x03A3 (931)\n404 0x3480 // X & 15 (Bit-Index)\n405 0x000F // Operand #0x000F (15)\n406 0x2800 // Speichere Shift-Count\n407 0x03A9 // Operand #0x03A9 (937)\n408 0x1800 // Lade Shift-Count\n409 0x03A9 // Operand #0x03A9 (937)\n410 0x4018 // Fertig wenn Count == 0\n411 0x01A8 // Operand #0x0000 (0)\n412 0x3440 // Count - 1\n413 0xFFFF // Operand #0xFFFF (65535)\n414 0x2800 // Speichere Count\n415 0x03A9 // Operand #0x03A9 (937)\n416 0x1800 // Lade Maske\n417 0x03A8 // Operand #0x03A8 (936)\n418 0x3580 // Maske >> 1\n420 0x2800 // Speichere Maske\n421 0x03A8 // Operand #0x03A8 (936)\n422 0x4000 // Loop Mask-Shift\n423 0x0198 // Operand #0x0198 (408)\n424 0x1800 // Lade wordAddr\n425 0x03A7 // Operand #0x03A7 (935)\n426 0x2800 // Patch Leseadresse\n427 0x01AD // Operand #0x01AD (429)\n428 0x1800 // Lade aktuellen Wortwert\n430 0x2800 // Speichere currWord\n431 0x03AA // Operand #0x03AA (938)\n432 0x1800 // Lade Color\n433 0x03A5 // Operand #0x03A5 (933)\n434 0x4018 // Wenn Color == 0 -> Clear Pixel\n435 0x01C0 // Operand #0x0000 (0)\n436 0x1800 // Lade Maske\n437 0x03A8 // Operand #0x03A8 (936)\n438 0x2800 // Patch OR-Operand\n439 0x01BB // Operand #0x01BB (443)\n440 0x1800 // Lade currWord\n441 0x03AA // Operand #0x03AA (938)\n442 0x34C0 // currWord | mask\n444 0x2800 // Speichere neues currWord\n445 0x03AA // Operand #0x03AA (938)\n446 0x4000 // Sprung zu Write\n447 0x01CC // Operand #0x0000 (0)\n448 0x1800 // Lade Maske\n449 0x03A8 // Operand #0x03A8 (936)\n450 0x3540 // ~mask (invertiert)\n452 0x2800 // Patch AND-Operand\n453 0x01C9 // Operand #0x01C9 (457)\n454 0x1800 // Lade currWord\n455 0x03AA // Operand #0x03AA (938)\n456 0x3480 // currWord & ~mask\n458 0x2800 // Speichere neues currWord\n459 0x03AA // Operand #0x03AA (938)\n460 0x1800 // Lade wordAddr\n461 0x03A7 // Operand #0x03A7 (935)\n462 0x2800 // Patch Schreibadresse\n463 0x01D3 // Operand #0x01D3 (467)\n464 0x1800 // Lade geändertes Wort\n465 0x03AA // Operand #0x03AA (938)\n466 0x2800 // Schrei